/* Workbook contents are treated only as data. No cell content is evaluated as code or HTML. */
const $ = s => document.querySelector(s);
const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='dox-finance-workbook-v1';
const REQUIRED=['사업명','발주기관','발주부서','발주담당자','발주담당자 연락처','발주담당자 이메일','수행장소','입찰방식','공급업체','공급업체 사업자등록번호','공급업체 대표자','공급업체 연락처','공급업체 담당자','입찰공고번호','낙찰통지서 번호','계약서 번호','발주번호','검수서 번호','세금계산서 승인번호','거래명세서 번호','총액(VAT 포함)','공급가액','부가가치세','검수일','주요 산출물','수행제안 요약'];
const DOCS=['입찰공고번호','낙찰통지서 번호','계약서 번호','발주번호','검수서 번호','세금계산서 승인번호','거래명세서 번호'];
let state, filter='all',view='overview',toastTimer;
const classify = r => !String(r.value??'').trim() ? 'warning' : String(r.status).trim()==='정상' ? 'normal' : /확인|주의|오류|불일치|누락/.test(r.status) ? 'warning' : 'other';
const get = label => state?.rows.find(r=>r.label===label)?.value ?? '';
function numeric(value){const s=String(value??'').replace(/[,₩원\s]/g,'');return s!==''&&Number.isFinite(Number(s))?Number(s):null;}
function money(value){const n=numeric(value);return n===null?'미입력':n.toLocaleString('ko-KR')+'원';}
function dateValue(value){if(typeof value==='number'){const d=XLSX.SSF.parse_date_code(value);return d?`${d.y}.${String(d.m).padStart(2,'0')}.${String(d.d).padStart(2,'0')}`:String(value);}return String(value??'');}
const display = r => r.label==='검수일'?dateValue(r.value):['총액(VAT 포함)','공급가액','부가가치세'].includes(r.label)?money(r.value):String(r.value??'')||'미입력';
function badge(r){const type=classify(r);return `<span class="badge ${type==='warning'?'amber':type==='normal'?'normal':'unknown'}">${type==='warning'?'◷':type==='normal'?'✓':'−'} ${escapeHTML(!String(r.value??'').trim()?'내용 미입력':r.status||'미분류')}</span>`;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function render(){
 const rows=state.rows, normal=rows.filter(r=>classify(r)==='normal'), warnings=rows.filter(r=>classify(r)==='warning'), other=rows.length-normal.length-warnings.length;
 const pct=rows.length?Math.round(normal.length/rows.length*100):0;
 $('#sourceName').textContent=state.filename;$('#sourceTime').textContent=state.importedAt?'최근 반영 '+new Date(state.importedAt).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'첨부 엑셀 기준';
 $('#metrics').innerHTML=[{label:'총 계약금액',value:money(get('총액(VAT 포함)')).replace(/원$/,''),unit:'원',foot:'VAT 포함 · 원본 금액',icon:'₩'},{label:'공급가액',value:money(get('공급가액')).replace(/원$/,''),unit:'원',foot:'부가가치세 제외',icon:'▤'},{label:'증빙서류 번호',value:DOCS.filter(d=>String(get(d)).trim()).length,unit:'건',foot:'원본에 기재된 서류 식별번호',icon:'▧'},{label:'확인 필요 항목',value:warnings.length,unit:'건',foot:warnings.length?'<span class="tiny-pill">검토 필요</span>원본 상태 및 미입력 기준':'모든 항목을 확인했습니다',icon:'◷',alert:true}].map(m=>`<div class="metric ${m.alert?'alert':''}"><div class="metric-label">${m.label}<span class="metric-icon">${m.icon}</span></div><div class="metric-value">${escapeHTML(m.value)}<small>${m.unit}</small></div><div class="metric-foot">${m.foot}</div></div>`).join('');
 $('#projectName').textContent=get('사업명')||'사업명 미입력';$('#projectOrg').textContent=`${get('발주기관')} · ${get('발주부서')}`;$('#bidNo').textContent=get('입찰공고번호')||'미입력';
 $('.section-kicker .badge').textContent=get('입찰방식')||'입찰방식 미입력';$('#projectStatus').textContent=warnings.length?`◷ ${warnings.length}개 항목 확인 필요`:'✓ 검토 항목 정상';$('#projectStatus').className='badge '+(warnings.length?'amber':'normal');
 $('#projectMeta').innerHTML=[['발주담당자',get('발주담당자')],['공급업체',get('공급업체')],['검수일',dateValue(get('검수일'))],['수행장소',get('수행장소')]].map(([l,v])=>`<div class="meta"><span>${l}</span><strong>${escapeHTML(v||'미입력')}</strong></div>`).join('');
 $('#navCount').textContent=warnings.length;$('#reviewCount').textContent=warnings.length;$('#reviewItems').innerHTML=warnings.length?warnings.slice(0,3).map(r=>`<div class="review-item"><span class="warning-icon">!</span><div><strong>${escapeHTML(r.label)}</strong><small>${escapeHTML(!String(r.value??'').trim()?'내용이 비어 있습니다':'원본 확인 상태: '+r.status)}</small></div><span class="review-amount">${escapeHTML(display(r))}</span></div>`).join(''):'<div class="empty-review">✓ 확인이 필요한 항목이 없습니다.</div>';
 const total=numeric(get('총액(VAT 포함)')),supply=numeric(get('공급가액')),vat=numeric(get('부가가치세'));
 $('#reconcile').innerHTML=[total,supply,vat].some(n=>n===null)?'금액 합계 비교: 금액이 누락되었거나 숫자 형식이 아닙니다.':Math.abs(supply+vat-total)<0.01?'<b>✓ 금액 합계 일치</b> · 공급가액 + 부가가치세 = 총액':'<span style="color:#bd8737">금액 합계 불일치 · 차액 '+escapeHTML(money(total-supply-vat))+'</span>';
 $('#percent').textContent=pct+'%';$('#donut').style.background=`conic-gradient(#167d79 0 ${normal.length/rows.length*100}%,#e5b56b 0 ${(normal.length+warnings.length)/rows.length*100}%,#dce2e8 0)`;
 $('#normalCount').textContent=normal.length+'건';$('#warningCount').textContent=warnings.length+'건';$('#otherCount').textContent=other+'건';$('#totalCount').textContent=rows.length+'개 항목';$('#allCount').textContent=rows.length;$('#tabWarningCount').textContent=warnings.length;$('#sheetName').textContent=state.sheet;
 renderTable();
}
function renderTable(){if(!state)return;const q=$('#search').value.trim().toLowerCase();const selected=state.rows.map((r,i)=>({...r,index:i+1})).filter(r=>(view!=='documents'||DOCS.includes(r.label))&&(view!=='review'||classify(r)==='warning')&&(filter==='all'||classify(r)===filter)&&(!q||[r.label,display(r),r.status].join(' ').toLowerCase().includes(q)));
 $('#tableBody').innerHTML=selected.length?selected.map(r=>`<tr class="${classify(r)==='warning'?'warning-row':''}"><td>${String(r.index).padStart(2,'0')}</td><td>${escapeHTML(r.label)}</td><td>${escapeHTML(display(r)).replace(/\n/g,'<br>')}</td><td>${badge(r)}</td><td>${escapeHTML('B'+r.sourceRow+' · C'+r.sourceRow)}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">조건에 맞는 항목이 없습니다.</td></tr>';
 $('#resultCount').textContent=`전체 ${state.rows.length}개 중 ${selected.length}개 표시`;
}
function selectView(name){view=name;filter='all';$('#search').value='';document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.filter==='all'));const names={overview:'입찰·정산 현황',details:'사업 상세정보',documents:'증빙서류',review:'검토 필요 항목'};$('#pageTitle').textContent=names[view];$('#crumb').textContent=names[view];$('#overview').hidden=view!=='overview';$('#tableTitle').textContent=view==='overview'?'사업 정보 및 증빙서류':names[view];$('#tableDescription').textContent=view==='documents'?'원본에 기재된 증빙서류 번호입니다. 실제 서류 파일의 제출 여부는 포함하지 않습니다.':view==='review'?'원본에서 확인이 필요하거나 내용이 비어 있는 항목입니다.':'엑셀의 모든 항목과 원본 확인 상태를 확인하세요.';renderTable();window.scrollTo({top:0,behavior:'smooth'});}
function parseWorkbook(workbook,filename){
 let selected;
 for(const name of workbook.SheetNames){const sheet=workbook.Sheets[name];if(!sheet['!ref'])continue;const range=XLSX.utils.decode_range(sheet['!ref']);if(range.e.r>10000||range.e.c>100)continue;const grid=XLSX.utils.sheet_to_json(sheet,{header:1,defval:'',raw:true});const headerIndex=grid.findIndex(row=>['항목','내용','확인'].every(label=>row.some(c=>String(c).trim()===label)));if(headerIndex<0)continue;
 const header=grid[headerIndex].map(c=>String(c).trim());const cols=['항목','내용','확인'].map(l=>header.indexOf(l));const rows=grid.slice(headerIndex+1).map((r,i)=>({label:String(r[cols[0]]??'').trim(),value:r[cols[1]]??'',status:String(r[cols[2]]??'').trim(),sourceRow:headerIndex+i+2})).filter(r=>r.label);
 const labels=rows.map(r=>r.label);const missing=REQUIRED.filter(l=>!labels.includes(l));if(missing.length)throw new Error('양식에 필요한 항목이 없습니다: '+missing.slice(0,3).join(', '));if(new Set(labels).size!==labels.length)throw new Error('중복된 항목명이 있습니다. 항목별로 한 행만 남겨 주세요.');selected={filename,sheet:name,rows,importedAt:new Date().toISOString()};break;
 }
 if(!selected)throw new Error('‘항목 · 내용 · 확인’ 열이 있는 시트를 찾지 못했습니다. 원본 양식을 확인해 주세요.');return selected;
}
async function importFile(file){if(!file)return;if(!/\.xlsx?$/i.test(file.name))return toast('XLSX 또는 XLS 형식의 파일을 선택해 주세요.');if(file.size>10*1024*1024)return toast('10MB 이하의 파일을 선택해 주세요.');try{const next=parseWorkbook(XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:false}),file.name);state=next;let saved=true;try{localStorage.setItem(KEY,JSON.stringify(state));}catch{saved=false;}$('#uploadDialog').close();selectView('overview');render();toast(saved?`${state.rows.length}개 항목을 반영하고 브라우저에 저장했습니다.`:'내용을 반영했습니다. 브라우저 저장 공간이 부족해 새로고침하면 복원되지 않습니다.');}catch(error){toast('업로드 실패: '+error.message);}finally{$('#fileInput').value='';}}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>selectView(b.dataset.view)));
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t===b));renderTable();}));
$('#search').addEventListener('input',renderTable);
$('#openUpload').onclick=()=>$('#uploadDialog').showModal();$('#closeDialog').onclick=()=>$('#uploadDialog').close();$('#uploadDialog').addEventListener('click',e=>{if(e.target===$('#uploadDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#chooseFile').onclick=e=>{e.stopPropagation();$('#fileInput').click();};$('#dialogChoose').onclick=()=>$('#fileInput').click();$('#dropzone').onclick=()=>$('#fileInput').click();$('#dropzone').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('#fileInput').click();}};$('#fileInput').onchange=e=>importFile(e.target.files[0]);
for(const event of ['dragenter','dragover'])$('#dropzone').addEventListener(event,e=>{e.preventDefault();$('#dropzone').classList.add('dragover');});$('#dropzone').ondragleave=()=>$('#dropzone').classList.remove('dragover');$('#dropzone').ondrop=e=>{e.preventDefault();$('#dropzone').classList.remove('dragover');importFile(e.dataTransfer.files[0]);};window.addEventListener('dragover',e=>e.preventDefault());window.addEventListener('drop',e=>e.preventDefault());
$('#templateDownload').onclick=()=>{const a=document.createElement('a');a.href='assets/bid-template.xlsx';a.download='DoxAI_입찰정산_원본양식.xlsx';a.click();};
$('#downloadReport').onclick=()=>{if(!state)return;const grid=[[get('사업명')+' · 입찰·정산 현황'],[],['항목','내용','확인'],...state.rows.map(r=>[r.label,r.label==='검수일'?dateValue(r.value):r.value,r.status])];const wb=XLSX.utils.book_new();const ws=XLSX.utils.aoa_to_sheet(grid);ws['!cols']=[{wch:26},{wch:90},{wch:14}];XLSX.utils.book_append_sheet(wb,ws,'최종확인');XLSX.writeFile(wb,'DOX_입찰정산_현황.xlsx');toast('현재 반영된 전체 항목을 내보냈습니다.');};
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('#uploadDialog').open){e.preventDefault();$('#search').focus();}});
async function init(){try{let cached;try{cached=JSON.parse(localStorage.getItem(KEY));}catch{}if(cached&&Array.isArray(cached.rows)&&cached.rows.length&&REQUIRED.every(l=>cached.rows.some(r=>r.label===l)))state=cached;else{const response=await fetch('assets/bid-template.xlsx');if(!response.ok)throw new Error('첨부 데이터를 불러오지 못했습니다.');state=parseWorkbook(XLSX.read(await response.arrayBuffer(),{type:'array'}),'DoxAI_Test01_Bid-Related Documents.xlsx');state.importedAt=null;}render();}catch(error){$('#sourceTime').textContent='데이터 로드 실패';toast(error.message+' 엑셀 파일을 업로드해 주세요.');}}
init();
